/// Fitted wrapped-normal HMM.
#[derive(Clone, Debug)]
pub struct FittedWrappedNormalHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Mean directions.
    pub mu: Vector,
    /// Circular scales.
    pub sigma: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedWrappedNormalHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let s = self.mu.len();
        let mut out = vec![vec![f64::NEG_INFINITY; s]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..s {
                out[ti][j] = log_wrapped_normal(y, self.mu[j], self.sigma[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedWrappedNormalHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for WrappedNormalHmm {
    type Fitted = FittedWrappedNormalHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedWrappedNormalHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        if t_len == 0 {
            return ctx.finish(FittedWrappedNormalHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                mu: Vector::zeros(k),
                sigma: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut mu = Vector::from_iter((0..k).map(|j| (j as f64 - 0.5) * 0.8));
        let mut sigma = Vector::filled(k, 1.0);
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedWrappedNormalHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                mu: mu.clone(),
                sigma: sigma.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut cs = 0.0_f64;
                let mut sn = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() {
                        continue;
                    }
                    let w = fb.gamma[t][j];
                    wsum += w;
                    cs += w * y.cos();
                    sn += w * y.sin();
                }
                if wsum > 1e-12 {
                    mu[j] = sn.atan2(cs);
                    let resultant = (cs * cs + sn * sn).sqrt() / wsum;
                    let r = resultant.clamp(1e-8, 1.0 - 1e-8);
                    sigma[j] = ((-2.0 * r.ln()).max(COV_FLOOR)).sqrt();
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedWrappedNormalHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            mu: mu.clone(),
            sigma: sigma.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedWrappedNormalHmm {
            labels,
            start,
            trans,
            mu,
            sigma,
            loglik,
        })
    }
}

