/// Lindley HMM (exponential–gamma mixture \((1+x)e^{-θx}\)).
///
/// Rate \(θ\) is not identification `p`. Distinct from [`GammaHmm`] (Erlang-2)
/// and [`ExponentialHmm`].
#[derive(Clone, Debug)]
pub struct LindleyHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for LindleyHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl LindleyHmm {
    /// `k`-state Lindley HMM.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(&mut self, x: &Matrix, session: &Session) -> Result<Qualified<FittedLindleyHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted Lindley HMM.
#[derive(Clone, Debug)]
pub struct FittedLindleyHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Rates \(θ\).
    pub theta: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedLindleyHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.theta.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_lindley(y, self.theta[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedLindleyHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for LindleyHmm {
    type Fitted = FittedLindleyHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedLindleyHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) <= 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!("LindleyHmm skipped {n_skip} non-positive observations"))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedLindleyHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                theta: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut theta = Vector::from_iter((0..k).map(|j| 0.4 + 0.3 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedLindleyHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                theta: theta.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wy += fb.gamma[t][j] * y;
                }
                if wsum > 1e-12 {
                    let m = (wy / wsum).max(0.2);
                    let disc = ((m - 1.0) * (m - 1.0) + 8.0 * m).sqrt();
                    theta[j] = ((-(m - 1.0) + disc) / (2.0 * m)).clamp(0.05, 8.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedLindleyHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            theta: theta.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedLindleyHmm {
            labels,
            start,
            trans,
            theta,
            loglik,
        })
    }
}

