impl FitUnsupervised for BilateralGammaHmm {
    type Fitted = FittedBilateralGammaHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedBilateralGammaHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        if t_len == 0 {
            return ctx.finish(FittedBilateralGammaHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                rate1: Vector::filled(k, 1.0),
                rate2: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut rate1 = Vector::from_iter((0..k).map(|j| 0.4 + 0.3 * j as f64));
        let mut rate2 = Vector::from_iter((0..k).map(|j| 0.5 + 0.2 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedBilateralGammaHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                rate1: rate1.clone(),
                rate2: rate2.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wp = 0.0_f64;
                let mut yp = 0.0_f64;
                let mut wm = 0.0_f64;
                let mut ym = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() {
                        continue;
                    }
                    if y >= 0.0 {
                        wp += fb.gamma[t][j];
                        yp += fb.gamma[t][j] * y;
                    } else {
                        wm += fb.gamma[t][j];
                        ym += fb.gamma[t][j] * (-y);
                    }
                }
                if wp > 1e-12 {
                    rate1[j] = (2.0 / (yp / wp).max(0.2)).clamp(0.1, 8.0);
                }
                if wm > 1e-12 {
                    rate2[j] = (2.0 / (ym / wm).max(0.2)).clamp(0.1, 8.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedBilateralGammaHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            rate1: rate1.clone(),
            rate2: rate2.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedBilateralGammaHmm {
            labels,
            start,
            trans,
            rate1,
            rate2,
            loglik,
        })
    }
}

