impl FitUnsupervised for ShiftedLogLogisticHmm {
    type Fitted = FittedShiftedLogLogisticHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedShiftedLogLogisticHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let (ymin, _ymax, span) = sample_span(x);
        let xi = if ymin.is_finite() {
            ymin - 0.05 * span
        } else {
            0.0
        };
        let shape = Vector::from_iter((0..k).map(|j| 1.4 + 1.2 * j as f64));
        if t_len == 0 {
            return ctx.finish(FittedShiftedLogLogisticHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                xi,
                scale: Vector::filled(k, 1.0),
                shape,
                loglik: f64::NAN,
            });
        }
        let mut scale = Vector::from_iter((0..k).map(|j| 1.0 + j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedShiftedLogLogisticHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                xi,
                scale: scale.clone(),
                shape: shape.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y <= xi {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wy += fb.gamma[t][j] * (y - xi);
                }
                if wsum > 1e-12 {
                    scale[j] = (wy / wsum).max(COV_FLOOR);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedShiftedLogLogisticHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            xi,
            scale: scale.clone(),
            shape: shape.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedShiftedLogLogisticHmm {
            labels,
            start,
            trans,
            xi,
            scale,
            shape,
            loglik,
        })
    }
}

