impl FitUnsupervised for WrappedGumbelHmm {
    type Fitted = FittedWrappedGumbelHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedWrappedGumbelHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let scale = Vector::from_iter((0..k).map(|j| 0.7 + 0.5 * j as f64));
        if t_len == 0 {
            return ctx.finish(FittedWrappedGumbelHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                loc: Vector::zeros(k),
                scale,
                loglik: f64::NAN,
            });
        }
        let mut loc = Vector::from_iter((0..k).map(|j| -0.4 + 0.8 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedWrappedGumbelHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                loc: loc.clone(),
                scale: scale.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut sx = 0.0_f64;
                let mut sy = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() {
                        continue;
                    }
                    let th = wrap_pi(y);
                    let w = fb.gamma[t][j];
                    sx += w * th.cos();
                    sy += w * th.sin();
                }
                if sx * sx + sy * sy > 1e-18 {
                    loc[j] = wrap_pi(sy.atan2(sx));
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedWrappedGumbelHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            loc: loc.clone(),
            scale: scale.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedWrappedGumbelHmm {
            labels,
            start,
            trans,
            loc,
            scale,
            loglik,
        })
    }
}

fn log_shanker(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    2.0 * theta.ln() - (theta * theta + 1.0).ln() + (theta + y).ln() - theta * y
}

fn log_sujatha(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    3.0 * theta.ln() - (theta * theta + theta + 2.0).ln() + (1.0 + y + y * y).ln() - theta * y
}

fn log_inv_chi(y: f64, nu: f64, scale: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || nu <= 0.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let a = 0.5 * nu;
    -(a - 1.0) * std::f64::consts::LN_2 - crate::special::ln_gamma(a) + nu * scale.ln()
        - (nu + 1.0) * y.ln()
        - (scale * scale) / (2.0 * y * y)
}

fn log_discrete_pareto(y: f64, lam: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || lam <= 0.0 || alpha <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let k = y.round().max(0.0);
    let ratio = ((lam + k) / (lam + k + 1.0)).powf(alpha);
    if !(ratio.is_finite() && ratio < 1.0) {
        return f64::NEG_INFINITY;
    }
    -alpha * (1.0 + k / lam).ln() + (1.0 - ratio).ln()
}

/// Shanker lifetime HMM (\((\theta+x)e^{-\\theta x}\)).
///
/// Rate \(\theta\) is not identification `p`. Distinct from [`LindleyHmm`]
/// (\((1+x)\)) and [`AkashHmm`] (\((1+x)^2\)).
#[derive(Clone, Debug)]
pub struct ShankerHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for ShankerHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl ShankerHmm {
    /// `k`-state Shanker HMM.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(&mut self, x: &Matrix, session: &Session) -> Result<Qualified<FittedShankerHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted Shanker HMM.
#[derive(Clone, Debug)]
pub struct FittedShankerHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Rates \(\theta_j\).
    pub theta: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedShankerHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.theta.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_shanker(y, self.theta[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedShankerHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for ShankerHmm {
    type Fitted = FittedShankerHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedShankerHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) <= 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!("ShankerHmm skipped {n_skip} non-positive observations"))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedShankerHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                theta: Vector::filled(k, 0.8),
                loglik: f64::NAN,
            });
        }
        let mut theta = Vector::from_iter((0..k).map(|j| 0.4 + 0.3 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedShankerHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                theta: theta.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut th = theta[j];
                for _ in 0..6 {
                    let mut g = 0.0_f64;
                    let mut gp = 0.0_f64;
                    for t in 0..t_len {
                        let y = x.get(t, 0);
                        if !y.is_finite() || y <= 0.0 {
                            continue;
                        }
                        let w = fb.gamma[t][j];
                        let t2 = th * th;
                        g += w * (2.0 / th - 2.0 * th / (t2 + 1.0) + 1.0 / (th + y) - y);
                        gp += w
                            * (-2.0 / (th * th) - 2.0 * (1.0 - t2) / ((t2 + 1.0) * (t2 + 1.0))
                                - 1.0 / ((th + y) * (th + y)));
                    }
                    if gp.abs() > 1e-12 {
                        th = (th - g / gp).clamp(1e-3, 40.0);
                    }
                }
                theta[j] = th;
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedShankerHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            theta: theta.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedShankerHmm {
            labels,
            start,
            trans,
            theta,
            loglik,
        })
    }
}

