fn log_disc_gompertz(y: f64, eta: f64, c: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || eta <= 0.0 || c <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let k = y.round().max(0.0);
    let ek = (eta * k).exp();
    if !ek.is_finite() {
        return f64::NEG_INFINITY;
    }
    let eh = eta.exp();
    if !eh.is_finite() {
        return f64::NEG_INFINITY;
    }
    let harg = c * ek * (eh - 1.0);
    if !harg.is_finite() || harg <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let log_s = -c * (ek - 1.0);
    let log_one_m = if harg > 20.0 {
        0.0
    } else if harg < 1e-12 {
        harg.ln()
    } else {
        (1.0 - (-harg).exp()).ln()
    };
    let v = log_s + log_one_m;
    if v.is_finite() {
        v
    } else {
        f64::NEG_INFINITY
    }
}

fn log_beta_weibull(y: f64, scale: f64, shape: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || scale <= 0.0 || shape <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let z = (y / scale).powf(shape);
    if !z.is_finite() {
        return f64::NEG_INFINITY;
    }
    let surv = (-z).exp();
    let cdf = (1.0 - surv).max(1e-15);
    let one_m = surv.max(1e-15);
    log_weibull(y, shape, scale) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln() - ln_beta(a, b)
}

fn log_mo_chen(y: f64, lam: f64, beta: f64, tilt: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || lam <= 0.0 || beta <= 0.0 || tilt <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let yb = y.powf(beta);
    if !yb.is_finite() || yb > 40.0 {
        return f64::NEG_INFINITY;
    }
    let surv = (-lam * (yb.exp() - 1.0)).exp();
    let den = 1.0 - (1.0 - tilt) * surv;
    if den <= 1e-12 {
        return f64::NEG_INFINITY;
    }
    tilt.ln() + log_chen(y, lam, beta) - 2.0 * den.ln()
}

fn log_beta_gompertz(y: f64, eta: f64, c: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || eta <= 0.0 || c <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let ey = (eta * y).exp();
    if !ey.is_finite() {
        return f64::NEG_INFINITY;
    }
    let surv = (-c * (ey - 1.0)).exp();
    let cdf = (1.0 - surv).max(1e-15);
    let one_m = surv.max(1e-15);
    log_gompertz(y, eta, c) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln() - ln_beta(a, b)
}

fn log_disc_inv_gamma(y: f64, shape: f64, scale: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || shape <= 0.0 || scale <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let k = y.round().max(0.0);
    let cdf = |x: f64| -> f64 {
        if x <= 0.0 {
            0.0
        } else {
            1.0 - crate::special::gamma_p(shape, scale / x)
        }
    };
    let lo = cdf(k);
    let hi = cdf(k + 1.0);
    if !lo.is_finite() || !hi.is_finite() {
        return f64::NEG_INFINITY;
    }
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Discrete Gompertz HMM (\(P(X=k)=S(k)-S(k+1)\)).
///
/// Growth \(\eta\) is a hyperparameter, not identification `p`. Distinct from
/// [`GompertzHmm`] (continuous) and [`DiscreteWeibullHmm`].
#[derive(Clone, Debug)]
pub struct DiscreteGompertzHmm {
    /// Hidden states. Not identification `p`.
    pub n_states: usize,
    /// Baum–Welch cap.
    pub max_iter: usize,
}

impl Default for DiscreteGompertzHmm {
    fn default() -> Self {
        Self {
            n_states: 2,
            max_iter: 40,
        }
    }
}

impl DiscreteGompertzHmm {
    /// `k`-state discrete-Gompertz HMM.
    pub fn new(n_states: usize) -> Self {
        Self {
            n_states,
            ..Self::default()
        }
    }

    /// Fit alias.
    pub fn fit(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedDiscreteGompertzHmm>> {
        self.fit_unsupervised(x, session)
    }
}

/// Fitted discrete Gompertz HMM.
#[derive(Clone, Debug)]
pub struct FittedDiscreteGompertzHmm {
    /// Viterbi path.
    pub labels: Vector,
    /// Start distribution.
    pub start: Vector,
    /// Transitions.
    pub trans: Matrix,
    /// Growth rates \(\eta_j\).
    pub eta: Vector,
    /// Shapes \(c_j\).
    pub c: Vector,
    /// Training log-likelihood.
    pub loglik: f64,
}

impl FittedDiscreteGompertzHmm {
    fn log_emit_seq(&self, x: &Matrix) -> Vec<Vec<f64>> {
        let t = x.nrows();
        let ns = self.c.len();
        let mut out = vec![vec![f64::NEG_INFINITY; ns]; t];
        for ti in 0..t {
            let y = x.get(ti, 0);
            for j in 0..ns {
                out[ti][j] = log_disc_gompertz(y, self.eta[j], self.c[j]);
            }
        }
        out
    }

    /// Viterbi path.
    pub fn decode(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        let ctx = FitCtx::with_session(session.child("decode"));
        let (path, _) = viterbi_path(&self.start, &self.trans, &self.log_emit_seq(x));
        ctx.finish(path)
    }
}

impl Predict for FittedDiscreteGompertzHmm {
    type Output = Vector;
    fn predict(&self, x: &Matrix, session: &Session) -> Result<Qualified<Vector>> {
        self.decode(x, session)
    }
}

impl FitUnsupervised for DiscreteGompertzHmm {
    type Fitted = FittedDiscreteGompertzHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedDiscreteGompertzHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let eta = Vector::from_iter((0..k).map(|j| 0.12 + 0.06 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) < 0.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "DiscreteGompertzHmm skipped {n_skip} negative observations"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedDiscreteGompertzHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                eta,
                c: Vector::filled(k, 1.0),
                loglik: f64::NAN,
            });
        }
        let mut c = Vector::from_iter((0..k).map(|j| 0.6 + 0.3 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedDiscreteGompertzHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                eta: eta.clone(),
                c: c.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut wex = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 0.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    wex += fb.gamma[t][j] * ((eta[j] * y).exp() - 1.0).max(1e-8);
                }
                if wsum > 1e-12 && wex > 1e-12 {
                    c[j] = (wsum / wex).clamp(0.05, 40.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedDiscreteGompertzHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            eta: eta.clone(),
            c: c.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedDiscreteGompertzHmm {
            labels,
            start,
            trans,
            eta,
            c,
            loglik,
        })
    }
}

