impl FitUnsupervised for DiscreteInverseNakagamiHmm {
    type Fitted = FittedDiscreteInverseNakagamiHmm;
    fn fit_unsupervised(
        &mut self,
        x: &Matrix,
        session: &Session,
    ) -> Result<Qualified<FittedDiscreteInverseNakagamiHmm>> {
        let mut ctx = FitCtx::with_session(session.clone());
        inspect_xy(&mut ctx.report, x, None, &ctx.policy);
        let t_len = x.nrows();
        let k = self.n_states.max(1);
        let m = Vector::from_iter((0..k).map(|j| 1.4 + 0.9 * j as f64));
        let mut n_skip = 0usize;
        for i in 0..t_len {
            if x.get(i, 0).is_finite() && x.get(i, 0) < 1.0 {
                n_skip += 1;
            }
        }
        if n_skip > 0 {
            ctx.push(
                Issue::builder(IssueCode::NonPositiveSeries)
                    .severity(signlred::Severity::Warning)
                    .message(format!(
                        "DiscreteInverseNakagamiHmm skipped {n_skip} observations below 1"
                    ))
                    .build(),
            );
        }
        if t_len == 0 {
            return ctx.finish(FittedDiscreteInverseNakagamiHmm {
                labels: empty_labels(0),
                start: init_start(k),
                trans: init_trans(k),
                omega: Vector::filled(k, 0.4),
                m,
                loglik: f64::NAN,
            });
        }
        let mut omega = Vector::from_iter((0..k).map(|j| 0.25 + 0.2 * j as f64));
        let mut start = init_start(k);
        let mut trans = init_trans(k);
        let mut loglik = f64::NEG_INFINITY;
        let mut last_gamma: Vec<Vec<f64>> = Vec::new();
        for it in 0..self.max_iter.max(1) {
            let dummy = FittedDiscreteInverseNakagamiHmm {
                labels: Vector::zeros(0),
                start: start.clone(),
                trans: trans.clone(),
                omega: omega.clone(),
                m: m.clone(),
                loglik,
            };
            let Some(fb) = scaled_forward_backward(&mut ctx, &start, &trans, &dummy.log_emit_seq(x))
            else {
                break;
            };
            loglik = fb.loglik;
            last_gamma = fb.gamma.clone();
            ctx.session.step(it as u64, -loglik, None);
            for j in 0..k {
                let mut wsum = 0.0_f64;
                let mut winv2 = 0.0_f64;
                for t in 0..t_len {
                    let y = x.get(t, 0);
                    if !y.is_finite() || y < 1.0 {
                        continue;
                    }
                    wsum += fb.gamma[t][j];
                    winv2 += fb.gamma[t][j] / (y * y);
                }
                if wsum > 1e-12 && winv2 > 1e-18 {
                    omega[j] = (winv2 / wsum).clamp(0.05, 20.0);
                }
            }
            let (ns, ntr) = hmm_em_trans(&fb.xi, &fb.gamma[0], k, t_len);
            start = ns;
            trans = ntr;
        }
        if !last_gamma.is_empty() {
            let occup: Vec<f64> = (0..k)
                .map(|j| last_gamma.iter().map(|g| g.get(j).copied().unwrap_or(0.0)).sum())
                .collect();
            diagnose_chain(&mut ctx, &start, &trans, &occup);
        }
        let dummy = FittedDiscreteInverseNakagamiHmm {
            labels: Vector::zeros(0),
            start: start.clone(),
            trans: trans.clone(),
            omega: omega.clone(),
            m: m.clone(),
            loglik,
        };
        let (labels, _) = viterbi_path(&start, &trans, &dummy.log_emit_seq(x));
        ctx.finish(FittedDiscreteInverseNakagamiHmm {
            labels,
            start,
            trans,
            omega,
            m,
            loglik,
        })
    }
}

fn log_unit_nakagami(y: f64, m: f64, omega: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || m <= 0.0 || omega <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_nakagami(y / (1.0 - y), m, omega) - 2.0 * (1.0 - y).ln()
}

fn log_beta_nakagami(y: f64, m: f64, omega: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || m <= 0.0 || omega <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = crate::special::gamma_p(m, m * y * y / omega);
    if !cdf.is_finite() || cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_nakagami(y, m, omega) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_nakagami(y: f64, m: f64, omega: f64, alpha: f64) -> f64 {
    if !y.is_finite() || y < 0.0 || m <= 0.0 || omega <= 0.0 || alpha <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = crate::special::gamma_p(m, m * y * y / omega);
    if !cdf.is_finite() || cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    alpha.ln() + log_nakagami(y, m, omega) + (alpha - 1.0) * cdf.ln()
}

fn log_unit_rice(y: f64, nu: f64, sigma: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || nu < 0.0 || sigma <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_rice(y / (1.0 - y), nu, sigma) - 2.0 * (1.0 - y).ln()
}

fn log_disc_nakagami(y: f64, m: f64, omega: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || m <= 0.0 || omega <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let lo = crate::special::gamma_p(m, m * kk * kk / omega);
    let hi = crate::special::gamma_p(m, m * (kk + 1.0) * (kk + 1.0) / omega);
    if !lo.is_finite() || !hi.is_finite() {
        return f64::NEG_INFINITY;
    }
    let p = (hi - lo).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

