fn pranav_rate_from_mean(m: f64) -> f64 {
    let m = m.max(1e-3);
    let mut lo = 1e-3_f64;
    let mut hi = 20.0_f64;
    for _ in 0..40 {
        let mid = 0.5 * (lo + hi);
        let t3 = mid * mid * mid;
        let pred = (t3 + 24.0) / (mid * (t3 + 6.0));
        if pred > m {
            lo = mid;
        } else {
            hi = mid;
        }
    }
    0.5 * (lo + hi)
}

fn pranav_cdf(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 {
        return 0.0;
    }
    let t2 = theta * theta;
    let t3 = t2 * theta;
    let den = t3 + 6.0;
    let num = den + t3 * y * y * y + 3.0 * t2 * y * y + 6.0 * theta * y;
    let surv = (-theta * y).exp() * num / den;
    if !surv.is_finite() {
        return 1.0 - 1e-15;
    }
    (1.0 - surv).clamp(0.0, 1.0 - 1e-15)
}

fn log_unit_pn(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || y >= 1.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    log_pranav(y / (1.0 - y), theta) - 2.0 * (1.0 - y).ln()
}

fn log_beta_pn(y: f64, theta: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = pranav_cdf(y, theta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let surv = (1.0 - cdf).max(1e-15);
    log_pranav(y, theta) + (a - 1.0) * cdf.ln() + (b - 1.0) * surv.ln() - ln_beta(a, b)
}

fn log_exp_pn(y: f64, theta: f64, power: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || power <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = pranav_cdf(y, theta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    power.ln() + log_pranav(y, theta) + (power - 1.0) * cdf.ln()
}

fn log_kuma_pn(y: f64, theta: f64, a: f64, b: f64) -> f64 {
    if !y.is_finite() || y <= 0.0 || theta <= 0.0 || a <= 0.0 || b <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let cdf = pranav_cdf(y, theta);
    if cdf <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    let fa = cdf.powf(a);
    let one_m = 1.0 - fa;
    if one_m <= 1e-15 {
        return f64::NEG_INFINITY;
    }
    a.ln() + b.ln() + log_pranav(y, theta) + (a - 1.0) * cdf.ln() + (b - 1.0) * one_m.ln()
}

fn log_disc_pn(y: f64, theta: f64) -> f64 {
    if !y.is_finite() || y < 1.0 || theta <= 0.0 {
        return f64::NEG_INFINITY;
    }
    let kk = y.round().max(1.0);
    let p = (pranav_cdf(kk + 1.0, theta) - pranav_cdf(kk, theta)).max(0.0);
    if p <= 1e-18 {
        f64::NEG_INFINITY
    } else {
        p.ln()
    }
}

/// Unit Pranav HMM on \((0,1)\) (Exp/Gamma(4) mix on \(u=x/(1-x)\)).
